package in.jharkhand.civic.controller;
import in.jharkhand.civic.repository.JsonStore; import in.jharkhand.civic.service.WorkflowService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final JsonStore s;private final WorkflowService w;public DashboardController(JsonStore s,WorkflowService w){this.s=s;this.w=w;}@GetMapping public Map<String,Object> dashboard(Authentication a){String role=a==null?"USER":a.getAuthorities().stream().map(x->x.getAuthority().replace("ROLE_","")).findFirst().orElse("USER");String id=a==null?"user-demo":a.getName();Map<String,Object>x=new LinkedHashMap<>();List<Map<String,Object>> probs=s.read("problems.json");if("USER".equals(role))probs=probs.stream().filter(p->id.equals(p.get("userId"))).toList();x.put("problems",probs);x.put("projects",w.projects());x.put("notifications",w.notifications(id));x.put("points",w.points(id));return x;}}
